(() => {
  const selectors = [
    '#corePriceDisplay_desktop_feature_div',
    '#corePrice_feature_div',
    '#priceblock_ourprice',
    '#priceblock_dealprice',
    '#price_inside_buybox',
    '.a-price .a-offscreen',
    '#buybox',
    '#twister',
    '#desktop_buybox'
  ];
  const data = {};
  for (const sel of selectors) {
    const els = [...document.querySelectorAll(sel)];
    data[sel] = els.slice(0,5).map(e => e.innerText || e.textContent).filter(Boolean);
  }
  data.title = document.querySelector('#productTitle')?.innerText?.trim() || document.title;
  data.bodyPrices = [...new Set((document.body.innerText.match(/(?:\$|USD\s*)\s?\d{1,3}(?:,\d{3})*(?:\.\d{2})?|EUR\s?\d{1,3}(?:,\d{3})*(?:\.\d{2})?/g) || []))].slice(0,30);
  return data;
})()

(() => {
  const html = document.documentElement.outerHTML;
  const matches = [];
  const patterns = [
    /\$\s?\d{1,3}(?:,\d{3})*(?:\.\d{2})?/g,
    /\"price\"\s*:\s*\"?\$?\d+(?:\.\d{2})?\"?/gi,
    /displayPrice[^,}]*[,}]/gi,
    /priceAmount[^,}]*[,}]/gi,
    /B0DDZJS3SB.{0,500}/gi
  ];
  for (const re of patterns) {
    let m; let count=0;
    while ((m = re.exec(html)) && count < 50) { matches.push(m[0]); count++; }
  }
  return {title: document.querySelector('#productTitle')?.innerText?.trim(), matches: [...new Set(matches)].slice(0,100)};
})()
